const TZ = 'Asia/Taipei';
const WEEK = ['一', '二', '三', '四', '五', '六', '日'];

const inputDate = String($('Start').first().json.date || '').trim();
let today = inputDate ? DateTime.fromISO(inputDate, { zone: TZ }) : $now.setZone(TZ);
if (!today.isValid) today = $now.setZone(TZ);
today = today.startOf('day');

const rows = $input.all().map(i => i.json).filter(r => r && r.Date && r.Name);
const apiOk = rows.length > 0;

const toISO = d => d.toFormat('yyyy-LL-dd');
const label = d => `${d.toFormat('yyyy/LL/dd')}（週${WEEK[d.weekday - 1]}）`;
const short = d => `${d.month}/${d.day}（${WEEK[d.weekday - 1]}）`;

// 證交所清單同時包含休市日與特殊交易日（開始交易日／最後交易日），日期為民國年 YYYMMDD
const closed = new Map();
const special = new Map();
for (const r of rows) {
  const s = String(r.Date).trim();
  if (!/^\d{7}$/.test(s)) continue;
  const iso = `${1911 + parseInt(s.slice(0, 3), 10)}-${s.slice(3, 5)}-${s.slice(5, 7)}`;
  const name = String(r.Name).trim().replace(/\s*\/\s*/g, '/');
  if (/開始交易|最後交易/.test(name)) special.set(iso, name);
  else closed.set(iso, name.includes('無交易') ? '封關期間無交易' : name);
}

const isWeekend = d => d.weekday >= 6;
const isOpen = d => !isWeekend(d) && !closed.has(toISO(d));

let next = today.plus({ days: 1 });
for (let i = 0; i < 60 && !isOpen(next); i++) next = next.plus({ days: 1 });

const tIso = toISO(today);
const todayOpen = isOpen(today);

let breakNotice = '';
if (todayOpen && apiOk) {
  const start = today.plus({ days: 1 });
  const days = Math.round(next.diff(start, 'days').days);
  const reasons = [];
  let hasWeekdayHoliday = false;
  for (let i = 0; i < days; i++) {
    const d = start.plus({ days: i });
    const iso = toISO(d);
    if (closed.has(iso) && !isWeekend(d)) hasWeekdayHoliday = true;
    const reason = closed.get(iso) || (isWeekend(d) ? '週末' : '');
    if (reason && !reasons.includes(reason)) reasons.push(reason);
  }
  if (hasWeekdayHoliday) {
    const end = next.minus({ days: 1 });
    const range = days === 1 ? short(start) : `${short(start)}～${short(end)}`;
    breakNotice = `📅 休市預告：${range}休市 ${days} 天（${reasons.join('、')}），${short(next)}恢復交易`;
  }
}

let specialNote = special.get(tIso) || '';
if (specialNote.includes('春節後開始交易')) specialNote += '（開紅盤）';
if (specialNote.includes('春節前最後交易')) specialNote += '（封關日）';

return [{
  json: {
    ok: apiOk,
    date: tIso,
    dateLabel: label(today),
    isWeekend: isWeekend(today),
    isTradingDay: todayOpen,
    closedReason: todayOpen ? '' : (closed.get(tIso) || '週末'),
    specialNote: specialNote ? `今日為${specialNote}` : '',
    nextTradingDate: toISO(next),
    nextTradingLabel: label(next),
    breakNotice,
    error: apiOk ? '' : '無法取得證交所休市日資料，僅依週末判斷'
  }
}];
